const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..');
const catalogFiles = [
  'locales/web-locales.js',
  'locales/landing-2026-copy.js',
  'locales/landing-2026-auto.js',
];
const consumerFiles = [
  'index.html',
  'web/index-i18n.js',
  'web/index-auth-ui.js',
  'web/index-auth.js',
  'web/index-public-data.js',
  'web/index-page.js',
  'web/homepage-v6.js',
];

const sandbox = { window: {} };
sandbox.globalThis = sandbox.window;
for (const file of catalogFiles) {
  vm.runInNewContext(fs.readFileSync(path.join(root, file), 'utf8'), sandbox, { filename: file });
}

const source = sandbox.window.DUVELA_WEB_I18N;
const landing = sandbox.window.DUVELA_LANDING_2026_COPY || {};
const automatic = sandbox.window.DUVELA_LANDING_2026_AUTO || {};
const consumers = consumerFiles
  .map((file) => fs.readFileSync(path.join(root, file), 'utf8'))
  .join('\n');

function withHomepageProductCopy(source) {
  return Object.assign({}, source, {
    productShowcaseKicker: source.productShowcaseKicker || source.navVideo,
    productShowcaseTitle: source.productShowcaseTitle || source.featTitle,
    productShowcaseSub: source.productShowcaseSub || source.featSub,
    productVideosTitle: source.productVideosTitle || source.f1t,
    productVideosText: source.productVideosText || source.f1p,
    productLiveTitle: source.productLiveTitle || source.f2t,
    productLiveText: source.productLiveText || source.f2p,
    productPracticeTitle: source.productPracticeTitle || source.practiceTitle,
    productPracticeText: source.productPracticeText || source.s2p || source.f3p,
    productCoursesTitle: source.productCoursesTitle || source.price2Title,
    productCoursesText: source.productCoursesText || source.price2Text,
    productWorkspaceTitle: source.productWorkspaceTitle || source.appsTitle,
    productWorkspaceText: source.productWorkspaceText || source.bizP,
    menuOpen: source.menuOpen || '☰',
    menuClose: source.menuClose || source.closeLabel,
    previewNote: 'DUVELA LIVE Duel',
  });
}

const english = withHomepageProductCopy(Object.assign(
  {},
  source.base.en,
  source.extra.en,
  landing.en,
  automatic.en
));
const requiredKeys = Object.keys(english).filter((key) => consumers.includes(key));
const base = {};

for (const locale of source.locales) {
  const code = locale.code;
  const merged = withHomepageProductCopy(Object.assign(
    {},
    source.base.en,
    source.extra.en,
    landing.en,
    automatic.en,
    source.base[code],
    source.extra[code],
    landing[code],
    automatic[code]
  ));
  base[code] = Object.fromEntries(requiredKeys.map((key) => [key, merged[key]]));
}

const payload = {
  version: source.version,
  storageKey: source.storageKey,
  locales: source.locales,
  base: { en: base.en },
  extra: { en: {} },
};
const output = `// Generated by scripts/build-homepage-locale-bundle.js.\n` +
  `(function (global) {\n` +
  `  global.DUVELA_WEB_I18N = ${JSON.stringify(payload)};\n` +
  `  global.DUVELA_LANDING_2026_COPY = {};\n` +
  `  global.DUVELA_LANDING_2026_AUTO = {};\n` +
  `  const pending = {};\n` +
  `  global.DUVELA_HOME_LOCALES = { ensure(code) {\n` +
  `    const catalog = global.DUVELA_WEB_I18N;\n` +
  `    if (catalog.base[code]) return Promise.resolve(catalog.base[code]);\n` +
  `    if (pending[code]) return pending[code];\n` +
  `    if (!catalog.locales.some((locale) => locale.code === code)) return Promise.reject(new Error('Unsupported locale: ' + code));\n` +
  `    pending[code] = new Promise((resolve, reject) => {\n` +
  `      const script = document.createElement('script');\n` +
  `      script.src = './locales/homepage/' + encodeURIComponent(code) + '.js?v=20261020-2';\n` +
  `      script.async = true;\n` +
  `      script.onload = () => resolve(catalog.base[code]);\n` +
  `      script.onerror = () => reject(new Error('Unable to load locale: ' + code));\n` +
  `      document.head.appendChild(script);\n` +
  `    });\n` +
  `    return pending[code];\n` +
  `  } };\n` +
  `  const supported = new Set(global.DUVELA_WEB_I18N.locales.map((locale) => locale.code));\n` +
  `  const requested = new URLSearchParams(global.location.search).get('lang');\n` +
  `  const saved = localStorage.getItem(global.DUVELA_WEB_I18N.storageKey);\n` +
  `  const browser = String(navigator.language || 'en').toLowerCase().split('-')[0];\n` +
  `  const initial = [requested, saved, browser, 'en'].map((value) => String(value || '').toLowerCase().split('-')[0]).find((code) => supported.has(code)) || 'en';\n` +
  `  global.DUVELA_HOME_LOCALES.initialLocale = initial;\n` +
  `  global.DUVELA_HOME_LOCALES.ready = global.DUVELA_HOME_LOCALES.ensure(initial).catch(() => global.DUVELA_WEB_I18N.base.en);\n` +
  `})(window);\n`;

const outputPath = path.join(root, 'locales/homepage-locales.js');
fs.writeFileSync(outputPath, output, 'utf8');
const localeDir = path.join(root, 'locales/homepage');
fs.mkdirSync(localeDir, { recursive: true });
for (const { code } of source.locales) {
  if (code === 'en') continue;
  const localeOutput = `// Generated by scripts/build-homepage-locale-bundle.js.\n` +
    `(function (global) { if (global.DUVELA_WEB_I18N) global.DUVELA_WEB_I18N.base[${JSON.stringify(code)}] = ${JSON.stringify(base[code])}; })(window);\n`;
  fs.writeFileSync(path.join(localeDir, `${code}.js`), localeOutput, 'utf8');
}
console.log(`[homepage-locales] ${source.locales.length} split locales, ${requiredKeys.length} keys, ${Buffer.byteLength(output)} byte bootstrap`);
